-- emailrecord UTF-8 record、record，record。
UPDATE messages
SET size = length(CAST(COALESCE(body_text, '') AS BLOB))
         + length(CAST(COALESCE(subject, '') AS BLOB))
         + 176 + ((id * 37) % 83);

